// Where the trip goes, filled in when the template is added.
const PLACE = {{place}};
const INK = '#121a2e';
const WHITE = '#FFFFFF';
const BERRY = { gradient: 'linear', from: [0.33, 0], to: [0.67, 1],
  stops: [{ light: '#bd4232', dark: '#983228' }, { light: '#b02a50', dark: '#8a1f40' }] };
const PAPER = { light: '#FFFFFF', dark: '#c5d6f0' };
const PLANE = 'M21 15.5v-2l-8-5V3.8a1.5 1.5 0 0 0-3 0v4.7l-8 5v2l8-2.5v5l-2 1.5V21l3.5-1 3.5 1v-1.5l-2-1.5v-5z';
const MONTHS = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'];
const AIRPORTS = { kyoto: 'KIX', osaka: 'KIX', tokyo: 'HND', paris: 'CDG', london: 'LHR', rome: 'FCO', lisbon: 'LIS',
  'new york': 'JFK', berlin: 'BER', madrid: 'MAD', barcelona: 'BCN', bali: 'DPS', 'san francisco': 'SFO',
  'los angeles': 'LAX', 'san diego': 'SAN', seattle: 'SEA', chicago: 'ORD', boston: 'BOS', miami: 'MIA',
  austin: 'AUS', denver: 'DEN', honolulu: 'HNL', hawaii: 'HNL', 'mexico city': 'MEX', cancun: 'CUN',
  toronto: 'YYZ', vancouver: 'YVR', 'hong kong': 'HKG', seoul: 'ICN', bangkok: 'BKK', singapore: 'SIN',
  sydney: 'SYD', dubai: 'DXB', istanbul: 'IST', athens: 'ATH', amsterdam: 'AMS', dublin: 'DUB', prague: 'PRG',
  vienna: 'VIE', 'cape town': 'CPT', 'buenos aires': 'EZE', 'rio de janeiro': 'GIG', lima: 'LIM', mumbai: 'BOM',
  delhi: 'DEL' };

// A place's airport: a known city's code, else the initials of a name of several words or the first three letters.
function code(place) {
  const p = (place || '').toLowerCase().trim();
  const hit = Object.keys(AIRPORTS).find((k) => p === k || p.startsWith(k + ' '));
  if (hit) return AIRPORTS[hit];
  const words = p.split(/\s+/).filter(Boolean);
  return (words.length > 1 ? words.map((w) => w[0]).join('') : words[0] || '').replace(/[^a-z]/gi, '').slice(0, 3)
    .toUpperCase();
}

// The ticket's outline: rounded corners and a round notch in each side where the stub tears off.
function outline(height, notch) {
  return 'M12 0H138A12 12 0 0 1 150 12V' + (notch - 7) + 'A7 7 0 0 0 150 ' + (notch + 7) + 'V' + (height - 12)
    + 'A12 12 0 0 1 138 ' + height + 'H12A12 12 0 0 1 0 ' + (height - 12) + 'V' + (notch + 7) + 'A7 7 0 0 0 0 '
    + (notch - 7) + 'V12A12 12 0 0 1 12 0Z';
}

// The barcode's stripes, the prototype's repeating 7-unit pattern of a wide bar and a thin one.
function bars(width) {
  let d = '';
  for (let x = 0; x < width; x += 7) {
    d += 'M' + x + ' 0h' + Math.min(2, width - x) + 'v22h-' + Math.min(2, width - x) + 'z';
    if (x + 3.5 < width) d += 'M' + (x + 3.5) + ' 0h' + Math.min(1, width - x - 3.5) + 'v22h-' + Math.min(1, width - x - 3.5) + 'z';
  }
  return d;
}

// The boarding pass, tilted on the right. Its paper sits twice: solid in the backdrop, which tinted and clear mode
// remove, and faint in the tree with the words, so in tinted mode the words still show.
function ticket(trip, u, ghost) {
  const height = 101;
  const notch = Math.round(height * 0.63);
  const to = code(PLACE) || '?';
  const from = trip && trip.from ? code(trip.from) || 'HOME' : 'HOME';
  const when = trip && trip.date ? MONTHS[Number(trip.date.slice(5, 7)) - 1] + ' ' + Number(trip.date.slice(8, 10))
    : 'SET DATE';
  const words = (value, size, extra) => Object.assign({ type: 'text', value, size: size * u, color: INK,
    lineLimit: 1 }, extra);
  return { type: 'zstack', padding: { top: 16 * u, trailing: 16 * u },
    frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'topTrailing' },
    children: [
      { type: 'zstack', align: 'top', frame: { width: 150 * u, height: height * u }, rotation: 5,
        shadow: ghost ? { color: '#460a1e59', radius: 6 * u, y: 6 * u } : null, children: [
          { type: 'path', d: outline(height, notch), viewBox: [0, 0, 150, height],
            fill: ghost ? PAPER : { light: '#FFFFFF40', dark: '#c5d6f040' } },
          !ghost && { type: 'vstack', align: 'leading', spacing: 0, padding: { top: 10 * u, horizontal: 11 * u },
            children: [
              { type: 'hstack', spacing: 4 * u, frame: { height: 21 * u }, children: [
                words(from, 25, { fontName: 'Bricolage Grotesque Display', minScale: 0.6 }),
                { type: 'spacer', minLength: 0 },
                { type: 'path', d: PLANE, viewBox: [0, 0, 24, 24], fill: '#ff5e7e', rotation: 90,
                  frame: { width: 18 * u, height: 18 * u } },
                { type: 'spacer', minLength: 0 },
                words(to, 25, { fontName: 'Bricolage Grotesque Display', minScale: 0.6 }) ] },
              { type: 'hstack', spacing: 6 * u, padding: { top: 6 * u }, children: [
                words(PLACE, 10.5, { weight: 'bold', opacity: 0.55, minScale: 0.3 }),
                { type: 'spacer', minLength: 0 },
                words(when, 10.5, { weight: 'bold' }) ] },
            ] },
          !ghost && { type: 'vstack', spacing: 8 * u, padding: { top: (notch - 5.5) * u }, children: [
            { type: 'path', d: 'M0 1H150', viewBox: [0, 0, 150, 2], frame: { width: 150 * u, height: 2 * u },
              stroke: { color: '#121a2e59', width: 2 * u, dash: [4 * u, 3 * u] } },
            { type: 'path', d: bars(128), viewBox: [0, 0, 128, 22], fill: INK,
              frame: { width: 128 * u, height: 22 * u } } ] },
        ] },
    ] };
}

function render(ctx) {
  // Sizes are in the prototype's units: a widget is 170 of them tall. Bricolage's line is 1.2 times its size where
  // the prototype's huge number sets 0.9, so the number is placed 0.15 of its size higher than its box.
  const u = ctx.height / 170;
  const trip = ctx.data.trip;
  const wide = ctx.family === 'medium';
  const days = trip && trip.date ? Math.round((new Date(trip.date) - new Date(ctx.today.date)) / 86400000) : null;
  const big = days === null ? '?' : days > 0 ? String(days) : days === 0 ? 'Today' : 'Home';
  const line = days === null ? 'tap to set the date' : days > 1 ? 'days until our trip' : days === 1
    ? 'day until our trip' : days === 0 ? 'have a wonderful trip' : 'tap to plan the next one';
  const column = wide ? Math.min(176, ctx.width / u - 190) * u : ctx.width - 32 * u;
  const at = (top, child) => ({ type: 'zstack', padding: { top: top * u, leading: 16 * u },
    frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'topLeading' }, children: [child] });

  return {
    type: 'zstack', align: 'topLeading',
    frame: { maxWidth: 'infinity', maxHeight: 'infinity' },
    widgetBackground: { type: 'zstack', frame: { maxWidth: 'infinity', maxHeight: 'infinity' }, background: BERRY,
      children: [wide && ticket(trip, u, true)] },
    children: [
      { type: 'button', action: 'plan', rowId: trip ? trip.id : null,
        label: PLACE + ', ' + (days === null ? 'set the date' : days > 0 ? big + ' ' + line + ', change the date' : days === 0
          ? 'today, have a wonderful trip, change the date' : 'home, plan the next one'),
        children: [
        { type: 'zstack', frame: { maxWidth: 'infinity', maxHeight: 'infinity' }, children: [
          at(15, { type: 'hstack', spacing: 5 * u, frame: { width: column, height: 16 * u, alignment: 'leading' },
            children: [
              { type: 'path', d: PLANE, viewBox: [0, 0, 24, 24], fill: WHITE, frame: { width: 15 * u, height: 15 * u } },
              { type: 'text', value: PLACE, size: 13 * u, weight: 'bold', color: WHITE, lineLimit: 1, minScale: 0.4 },
            ] }),
          at(23.6, { type: 'text', value: big, fontName: 'Bricolage Grotesque Display', size: 76 * u,
            kerning: -3.04 * u, color: { light: '#fff6ef', dark: '#fff6ef' }, accent: true, lineLimit: 1,
            minScale: 0.4, frame: { maxWidth: column, alignment: 'leading' } }),
          at(108.4, { type: 'text', value: line, size: 12.5 * u, weight: 'semibold', color: WHITE, lineLimit: 1,
            minScale: 0.7, frame: { maxWidth: column, alignment: 'leading' } }),
          wide && ticket(trip, u, false),
        ] } ] },
    ],
  };
}
